import six
import re
import time
import logging
from abc import ABCMeta, abstractmethod
from taf.internal.managedobject import ManagedObject
from taf.internal.managed.ssh.managed_ssh_connection import ManagedSshConnection


class CommandOutputTimeoutError(Exception):
    pass


class IperfRemoteHost(ManagedObject):
    """
    assume accessing remote host via SSH, so the CMDs will be unix-like
    """

    def __init__(self, host, username, password, port=22, logger=None):
        super(IperfRemoteHost, self).__init__()
        self._ssh = ManagedSshConnection(host, username, password, port)
        self.add_prerequisite(self._ssh)
        self._ssh_process = None
        self._logger = logger or logging

    @staticmethod
    def _convert_str_to_bytes(string):
        if isinstance(string, six.string_types):
            string = string.encode('utf-8')
        return string

    def execute(self, command, timeout=None, get_pty=False):
        """
        execute command through ssh

        :param command: command that user want to execute
        :type command: str
        :param timeout: (optional) timeout for command execution
        :type timeout: int
        :param get_pty: (optional) if True, create a pty for the sent command, False by default
        :type get_pty: bool
        :return str : output after command execute
        """
        return self._execute(command=command, timeout=timeout) \
            if get_pty else self.run(command, timeout=timeout)

    def _execute(self, command, timeout):
        out = self._ssh.ssh_connection.execute(command=command, timeout=timeout)
        return self._convert_str_to_bytes(out)

    def run(self, command, timeout=None):
        self._send_command(command)
        out = self._read_output(timeout)
        return self._convert_str_to_bytes(out)

    def stop_from_command(self, command):
        self._send_command(command)

    def _send_command(self, command):
        """
        execute command through ssh

        :param command: command that user want to execute
        :type command: str
        """
        self._logger.debug("send command {}".format(command))
        self._ssh_process = self._ssh.ssh_connection.send_command(command=command)

    def _read_output(self, timeout):
        """

        :param timeout: timeout for read output
        :type timeout: int
        :return str : output after command execute
        """
        timeout = timeout or 60
        end_time = time.time() + timeout
        while time.time() < end_time:
            return self._ssh_process.read_output()
        raise CommandOutputTimeoutError("wait command output for {}s timeout".format(timeout))


@six.add_metaclass(ABCMeta)
class ForcePortAvailable(object):
    def __init__(self, host_config, logger=None):
        self._host_config = host_config
        self._logger = logger or logging
        self._host = None
        self._init_host()

    @property
    def netstat_options(self):
        raise NotImplementedError()

    def _init_host(self):
        self._host = IperfRemoteHost(host=self._host_config['host'],
                                     username=self._host_config['username'],
                                     password=self._host_config['password'])
        self._host.setup()

    def query_pid_by_port(self, port):
        pids = []

        cmd = self._generate_query_pid_command(port)
        out = self._host.execute(cmd)
        # output from appserver host(CentOS)
        # b'udp        0      0 10.57.163.51:5001       0.0.0.0:*                           24742/iperf\n'
        # b'udp        0      0 10.57.163.51:5001       172.250.186.64:54428    ESTABLISHED 24742/iperf\n'
        # b'udp        0      0 10.57.163.51:54857      172.250.186.64:5001     ESTABLISHED 24807/iperf\n'
        # b'tcp6       0      0 :::54009                :::*                    LISTEN      1564/iperf3'
        # output from Windows host
        # 'TCP    0.0.0.0:54001          0.0.0.0:0              LISTENING       31704'
        # 'TCP    10.57.150.116:54001    10.57.157.12:56686     ESTABLISHED     31704'
        # 'UDP    0.0.0.0:54001          *:*                                    13876'
        self._logger.debug("output from command {} is: {}".format(cmd, out))
        if isinstance(out, bytes):
            split_str = b'\r\n' if b'\r' in out else b'\n'
        else:
            split_str = '\r\n' if '\r' in out else '\n'
        lines = out.split(split_str)

        for line in lines:
            if not line:
                continue
            pid = self._analyze_netstat_line(line, port)
            if pid:
                pids.append(pid)
        return pids

    @abstractmethod
    def force_kill(self, pid):
        raise NotImplementedError()

    def force_port_available(self, port):
        pid_list = self.query_pid_by_port(port)
        self._logger.info('iperf process with the port in use: {}'.format(pid_list))
        for pid in pid_list:
            self.force_kill(pid)
        self._logger.info('force the port in use available by kill iperf process: {}'.format(pid_list))

    def _generate_query_pid_command(self, port):
        """Generate the command of querying iperf pid, override it"""
        raise NotImplementedError()

    @staticmethod
    def _get_pid(line, pattern_str):
        if isinstance(line, bytes):
            pattern_str = pattern_str.encode('utf-8')
        pattern = re.compile(pattern=pattern_str)
        result = pattern.match(line)
        if not result:
            return None
        return int(result.groupdict()['pid'])

    def _analyze_netstat_line(self, line, port):
        pattern = r'.*[\d\.:]+:{port}'.format(port=port) + r'\s+[\d:*].*\s{1,}(?P<pid>\d+)/iperf'
        return self._get_pid(line, pattern)


class AppserverForcePortAvailable(ForcePortAvailable):

    def __init__(self, ue_config, logger=None):
        host_config = self._get_host_config(ue_config)
        super(AppserverForcePortAvailable, self).__init__(host_config, logger)

    @property
    def netstat_options(self):
        return "-anp"

    @staticmethod
    def _get_host_config(ue_config):
        return {"host": ue_config.data_transfer[0].app_server.address,
                "username": ue_config.data_transfer[0].app_server.user,
                "password": ue_config.data_transfer[0].app_server.password}

    def force_kill(self, pid):
        force_cmd = 'kill -9 {pid}'.format(pid=pid)
        self._host.stop_from_command(force_cmd)

    def _generate_query_pid_command(self, port):
        filter_str = '-E .*:{port}.*/iperf'.format(port=port)
        cmd = "netstat {options} | grep {filter_str}".format(options=self.netstat_options, filter_str=filter_str)
        return cmd


class UepcForcePortAvailable(ForcePortAvailable):

    def __init__(self, ue_config, logger=None):
        host_config = self._get_host_config(ue_config)
        super(UepcForcePortAvailable, self).__init__(host_config, logger)

    @property
    def netstat_options(self):
        return "-ano"

    @staticmethod
    def _get_host_config(ue_config):
        return {"host": ue_config.ue_pc_address,
                "username": ue_config.ue_pc_login,
                "password": ue_config.ue_pc_password}

    def force_kill(self, pid):
        force_cmd = 'TASKKILL /T /F /PID {pid}'.format(pid=pid)
        self._host.execute(force_cmd)

    def _generate_query_pid_command(self, port):
        cmd = "netstat {options} | findstr {port}".format(options=self.netstat_options, port=port)
        return cmd

    def _analyze_netstat_line(self, line, port):
        pattern = r'.*[\d\.:]+:{port}'.format(port=port) + r'\s+[\d:*].*\s{1,}(?P<pid>\d+)'
        return self._get_pid(line, pattern)
